INSERT INTO kg_document_chunk (id, document_id, product_line, product_version, chunk_index, content, milvus_id, created_at, updated_at) VALUES
(1, 1, 'ECS', 'V3.2', 1, 'ECS 内网连通性基础排查：当云主机之间或云主机与 RDS 之间内网不通时，按以下顺序排查。第一步，确认云主机处于运行中状态：在控制台实例列表查看状态，或通过 API DescribeInstances 查询，状态应为 RUNNING。第二步，确认内网 IP 配置正确：登录云主机执行 ip addr show，确认主网卡已获取 VPC 分配的内网地址；若未获取到，检查 DHCP 服务或静态 IP 配置。第三步，验证基础连通性：从源端执行 ping 目标内网IP，再用 telnet 目标内网IP 端口号 验证端口可达性，例如 telnet 192.168.10.25 3306。ping 通但端口不通，通常是安全组或对端服务监听问题；ping 不通则优先查路由和网卡。第四步，通过云监控查看网卡丢包率与带宽使用率，确认是否触发了内网带宽限速。', 'mv_000001', '2026-07-28 10:02:10', '2026-07-28 10:02:31'),
(2, 1, 'ECS', 'V3.2', 2, 'ECS 安全组规则配置要点：安全组是云主机级别的虚拟防火墙，按规则优先级从小到大依次匹配，命中即生效。排查端口不通问题时，先检查出方向规则：默认全放行，若被收紧需确认目标网段和端口已放行；再检查入方向规则：确认允许源端所在网段访问对应端口，例如放行 192.168.0.0/16 访问 TCP 3306。常见错误：只配置了入方向却忽略了出方向；源地址写成了对端公网 IP 而非内网网段；多条规则优先级冲突导致放行规则被上层的拒绝规则覆盖。修改安全组规则实时生效，无需重启云主机。注意：RDS 实例有独立的访问白名单，与 ECS 安全组是两层独立控制，需要分别配置。', 'mv_000002', '2026-07-28 10:02:15', '2026-07-28 10:02:31'),
(3, 1, 'ECS', 'V3.2', 3, '弹性网卡与多内网 IP 配置：单台 ECS 最多可绑定 4 张弹性网卡，每张网卡必须属于同一可用区内的不同子网。为网卡配置辅助私网 IP 后，需在操作系统内手工添加地址，CentOS 示例：ip addr add 192.168.10.30/24 dev eth0，并使用 ip rule 和 ip route 配置策略路由，避免多网卡回程流量走错网卡导致非对称丢包。典型症状是 ping 主 IP 通、辅助 IP 不通。云主机热迁移或变配后需重新校验网卡路由策略。', 'mv_000003', '2026-07-28 10:02:20', '2026-07-28 10:02:31'),
(4, 2, 'VPC', 'V1.5', 1, 'VPC 路由表排查（案例编号 VPC-2025-047）：客户反馈同 VPC 内 ECS 访问 RDS 内网超时，检查安全组与白名单均正常。最终定位为子网关联了自定义路由表，其中一条指向 NAT 网关的默认路由 0.0.0.0/0 覆盖了系统路由，且自定义路由表缺少 RDS 所在网段 192.168.10.0/24 的 local 路由。排查步骤：第一步，在 VPC 控制台查看子网关联的路由表；第二步，比对路由表目标网段是否覆盖通信双方的网段，系统路由优先级低于最长前缀匹配的自定义路由；第三步，使用 vpc-route-lookup 工具或路由表模拟功能验证下一跳；第四步，恢复 local 路由后业务恢复。经验：修改自定义路由表前必须先确认 local 路由存在，跨子网访问异常优先怀疑路由表关联关系。', 'mv_000004', '2026-07-28 10:10:50', '2026-07-28 10:11:12'),
(5, 2, 'VPC', 'V1.5', 2, '跨域组网（云间高速）故障案例（案例编号 VPC-2025-112）：客户北京与上海两个 VPC 通过云间高速互联，业务高峰期出现跨域访问丢包率 30% 以上。定位为跨域带宽包超限：云间高速按带宽包限速，超限后直接丢包且不返回明确报错。排查步骤：第一步，在云间高速控制台查看带宽包利用率监控，峰值达到 100% 即确认超限；第二步，临时提升带宽包规格验证，丢包立即消失；第三步，长期方案为扩容带宽包或对跨域流量做 QoS 分级。另一高发案例是两端 VPC 网段冲突（如都是 172.16.0.0/16），此时无法建立互联，需通过 NAT 转换或更换网段解决。', 'mv_000005', '2026-07-28 10:10:55', '2026-07-28 10:11:12'),
(6, 2, 'VPC', 'V1.5', 3, '网络 ACL 与安全组叠加丢包案例（案例编号 VPC-2025-089）：子网级网络 ACL 与云主机级安全组同时生效，流量需两层都放行。客户只在安全组放行了 3306 端口，但子网 ACL 的默认拒绝规则丢弃了 RDS 返回的临时端口流量（1024-65535）。症状表现为 TCP 连接能建立但响应随机超时，极具迷惑性。排查方法：在 VPC 控制台查看子网 ACL 规则，确认出方向放行了临时端口段；或使用流量镜像功能抓包确认丢包点。经验：网络 ACL 是无状态的，出方向必须放行临时端口；安全组是有状态的，只需关注连接发起方向。', 'mv_000006', '2026-07-28 10:11:00', '2026-07-28 10:11:12'),
(7, 3, 'RDS', 'V2.0', 1, 'RDS 主备切换的前提与影响：RDS 高可用实例由主节点和备节点组成，应用通过统一 VIP 接入。主备切换会造成 30 秒左右的连接闪断，切换期间 VIP 发生漂移，未配置自动重连的应用会报连接失败。执行切换前必须确认：第一，当前无长事务和大事务执行中，否则切换时间会被拉长；第二，备节点复制延迟（Seconds_Behind_Master）为 0，可在控制台监控或执行 SHOW SLAVE STATUS 确认，延迟不为 0 时切换可能造成数据丢失；第三，应用连接池已配置重试机制。切换属于高危变更，必须在变更窗口内执行并提前通知业务方。', 'mv_000007', '2026-07-28 10:20:40', '2026-08-02 09:15:40'),
(8, 3, 'RDS', 'V2.0', 2, 'RDS 主备切换操作步骤（V2.0 版）：第一步，冻结写流量：在应用侧或接入层暂停写入，或执行 rds-cli freeze-writes --instance-id rm-bp1xxxx 将实例置为只读，这是 V2.0 相对旧版新增的强制步骤，用于避免切换瞬间产生脑裂写。第二步，执行切换命令：rds-cli switchover --instance-id rm-bp1xxxx --target-node standby，命令返回 task_id。第三步，跟踪任务进度：rds-cli describe-task --task-id 上一步返回的ID，状态变为 SUCCESS 即完成，一般耗时 30 到 60 秒。第四步，解冻写流量：rds-cli unfreeze-writes --instance-id rm-bp1xxxx。注意：未冻结写流量直接切换会导致最后几秒写入丢失，这是历史事故的主要根因。', 'mv_000008', '2026-07-28 10:20:45', '2026-08-02 09:15:40'),
(9, 3, 'RDS', 'V2.0', 3, 'RDS 主备切换后的验证清单：第一，确认新主节点角色：连接实例执行 SHOW SLAVE STATUS 应无返回行（该实例已是主），在控制台拓扑图确认主备角色已互换。第二，验证 VIP 漂移结果：执行 dig 实例连接地址 确认解析到新的主节点 IP。第三，验证复制链路：在新备节点执行 SHOW SLAVE STATUS，确认 Slave_IO_Running 和 Slave_SQL_Running 均为 Yes，Seconds_Behind_Master 为 0。第四，业务验证：观察应用连接池重建情况，抽测核心读写接口。第五，观察 30 分钟监控，确认无慢查询突增、无连接数异常后再关闭变更单。', 'mv_000009', '2026-07-28 10:20:50', '2026-08-02 09:15:40'),
(10, 4, 'RDS', 'V2.0', 1, 'DescribeDBInstances 接口：查询 RDS 实例列表。请求参数：RegionId（必填，地域 ID，如 cn-beijing）；DBInstanceStatus（可选，实例状态过滤，如 Running）；PageSize（可选，每页条数，最大 100，默认 30）；PageNumber（可选，页码，默认 1）。返回字段：DBInstances 数组，每项含 DBInstanceId、DBInstanceDescription、RegionId、ZoneId、DBInstanceStatus、ConnectionString（内网连接地址）、Port。分页查询时注意 TotalCount 与 PageSize 计算总页数。该接口限流为每秒 20 次，批量巡检脚本需加间隔。', 'mv_000010', '2026-07-28 10:31:30', '2026-07-28 10:31:55'),
(11, 4, 'RDS', 'V2.0', 2, 'SwitchDBInstanceHA 接口：触发 RDS 高可用实例主备切换。请求参数：DBInstanceId（必填，实例 ID）；TargetNodeType（可选，目标节点类型，取值 Standby，默认切换到备节点）；EffectiveTime（可选，执行时间，Immediate 立即执行 或 MaintainTime 在可维护时间段执行，默认 Immediate）。返回字段：TaskId（异步任务 ID，需用 DescribeTaskInfo 轮询任务状态）。注意：调用前必须确认实例状态为 Running 且复制延迟为 0；立即执行会造成约 30 秒连接闪断，生产实例建议先冻结写流量再调用。该接口为高危操作，建议在变更窗口内调用。', 'mv_000011', '2026-07-28 10:31:35', '2026-07-28 10:31:55');
